-- Migration 101: CEO Dashboard + MP Integration
-- Tables: dashboard_snapshots, mp_marketing_triggers

-- ═══════════════════════════════════════════
-- 1. Dashboard Snapshots
-- Periodic aggregated metrics for fast dashboard loading.
-- Generated by a scheduled job (daily or on-demand).
-- ═══════════════════════════════════════════

CREATE TABLE IF NOT EXISTS dashboard_snapshots (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id UUID NOT NULL,

  snapshot_date DATE NOT NULL,
  period_type TEXT NOT NULL DEFAULT 'daily'
    CHECK (period_type IN ('daily', 'weekly', 'monthly')),

  -- Email / VA2 Metrics (Month 1)
  emails_created INTEGER DEFAULT 0,
  emails_sent INTEGER DEFAULT 0,
  va2_manifests_generated INTEGER DEFAULT 0,
  top_theme TEXT,
  avg_section_count NUMERIC(4,1),

  -- Batch Metrics (Month 2)
  batch_jobs_created INTEGER DEFAULT 0,
  batch_jobs_completed INTEGER DEFAULT 0,
  batch_jobs_failed INTEGER DEFAULT 0,
  total_derivatives_generated INTEGER DEFAULT 0,
  channel_success_rates JSONB DEFAULT '{}'::jsonb,

  -- Performance Metrics (Month 3)
  avg_open_rate NUMERIC(5,4),
  avg_click_through_rate NUMERIC(5,4),
  avg_conversion_rate NUMERIC(5,4),
  top_performing_content_id UUID,
  top_performing_open_rate NUMERIC(5,4),
  campaigns_with_data INTEGER DEFAULT 0,

  -- Compliance Metrics (Month 4)
  compliance_scans_total INTEGER DEFAULT 0,
  compliance_pass_rate NUMERIC(5,4),
  avg_compliance_score NUMERIC(5,2),
  common_violations JSONB DEFAULT '[]'::jsonb,

  -- Competitor Metrics (Month 5)
  competitor_events_discovered INTEGER DEFAULT 0,
  significant_competitor_moves INTEGER DEFAULT 0,
  active_competitors_count INTEGER DEFAULT 0,
  top_competitor_event_type TEXT,

  -- Content Pipeline
  content_in_draft INTEGER DEFAULT 0,
  content_in_review INTEGER DEFAULT 0,
  content_approved INTEGER DEFAULT 0,
  content_published INTEGER DEFAULT 0,

  -- Team Performance
  active_team_members INTEGER DEFAULT 0,
  content_per_member NUMERIC(5,2),

  -- Metadata
  generated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  generation_duration_ms INTEGER,

  UNIQUE(organization_id, snapshot_date, period_type)
);

CREATE INDEX IF NOT EXISTS idx_dashboard_snapshots_org_date
  ON dashboard_snapshots(organization_id, snapshot_date DESC);

-- ═══════════════════════════════════════════
-- 2. MP Marketing Triggers
-- Records Merit Point earning events from marketing performance.
-- ═══════════════════════════════════════════

CREATE TABLE IF NOT EXISTS mp_marketing_triggers (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  organization_id UUID NOT NULL,

  user_id UUID NOT NULL,

  trigger_type TEXT NOT NULL
    CHECK (trigger_type IN (
      'high_open_rate',
      'high_ctr',
      'high_conversion',
      'perfect_compliance',
      'batch_completion',
      'top_performer',
      'competitor_insight',
      'streak_bonus'
    )),

  content_id UUID,
  batch_job_id UUID,
  compliance_scan_id UUID,

  points_earned INTEGER NOT NULL,
  multiplier NUMERIC(3,2) DEFAULT 1.0,

  details JSONB DEFAULT '{}'::jsonb,

  status TEXT DEFAULT 'pending'
    CHECK (status IN ('pending', 'credited', 'expired', 'cancelled')),
  credited_at TIMESTAMPTZ,

  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_mp_triggers_user
  ON mp_marketing_triggers(organization_id, user_id, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_mp_triggers_status
  ON mp_marketing_triggers(organization_id, status)
  WHERE status = 'pending';

CREATE INDEX IF NOT EXISTS idx_mp_triggers_type
  ON mp_marketing_triggers(organization_id, trigger_type, created_at DESC);

-- ═══════════════════════════════════════════
-- 3. RLS
-- ═══════════════════════════════════════════

ALTER TABLE dashboard_snapshots ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS dashboard_snapshots_org_isolation ON dashboard_snapshots;
CREATE POLICY dashboard_snapshots_org_isolation ON dashboard_snapshots
  USING (organization_id = current_setting('app.current_tenant', true)::uuid)
  WITH CHECK (organization_id = current_setting('app.current_tenant', true)::uuid);

ALTER TABLE mp_marketing_triggers ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS mp_triggers_org_isolation ON mp_marketing_triggers;
CREATE POLICY mp_triggers_org_isolation ON mp_marketing_triggers
  USING (organization_id = current_setting('app.current_tenant', true)::uuid)
  WITH CHECK (organization_id = current_setting('app.current_tenant', true)::uuid);
